using System;
using System.Linq;
using System.IO;
using System.Collections.Generic;
class Feature521Tests {
 static int checks,failures;static void Check(string s,bool ok){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+s);if(!ok)failures++;}
 static int Main(string[] args){Directory.CreateDirectory(args[0]);Check("custom points normalize",ReminderPoints.Parse("30, 7，7, 0").SequenceEqual(new[]{30,7,0}));bool bad=false;try{ReminderPoints.Parse("-1");}catch(ArgumentException){bad=true;}Check("invalid point rejected",bad);
 var e=new SkillEngine(new SkillData());e.SetWorkEnds(true,2,new[]{new WorkEndSlot{Label="下午",Enabled=true,MinuteOfDay=1080}});e.Data.EndOfWork.AdvanceMinutes=ReminderPoints.Parse("30,7,0");var local=new DateTime(2026,10,22,17,30,0,DateTimeKind.Local);Check("custom work point fires",e.Tick(local.ToUniversalTime()).Any(x=>x.Count==30));Check("work point deduplicates",!e.Tick(local.AddSeconds(10).ToUniversalTime()).Any(x=>x.Key.StartsWith("work-end:")));Check("removed defaults silent",!e.Tick(local.AddMinutes(15).ToUniversalTime()).Any(x=>x.Key.StartsWith("work-end:")));Check("zero means exact work time",e.Tick(local.AddMinutes(30).ToUniversalTime()).Any(x=>x.Count==0));Check("zero does not repeat after deadline",!e.Tick(local.AddMinutes(30).AddSeconds(1).ToUniversalTime()).Any(x=>x.Key.StartsWith("work-end:")));
 var now=DateTime.UtcNow;var r=e.AddCountdown("测试",30,now);e.SetReminderPoints(r.Id,new[]{7,0});Check("ordinary timer advance point",e.Tick(now.AddMinutes(23)).Any(x=>x.Key=="timer:"+r.Id));Check("ordinary timer remains enabled",r.Enabled);Check("ordinary deadline still fires",e.Tick(now.AddMinutes(30)).Any(x=>x.Key=="timer:"+r.Id));
 var days=new[]{new TrafficDay{Day="2024-02-29",Download=1048576,Upload=512}};var month=TrafficHistory.Range(days,new DateTime(2024,2,20),true);Check("leap month complete",month.Length==29);Check("missing dates remain unknown",month.Count(x=>x.Recorded)==1);Check("month totals exact",month.Sum(x=>x.Download)==1048576);var week=TrafficHistory.Range(days,new DateTime(2024,3,1),false);Check("week crosses month",week[0].Date==new DateTime(2024,2,26)&&week.Length==7);
 var cfg=new MonitorConfig{TaskbarItems=new List<string>{"cpu"}};cfg.Appearance.Transparent=false;cfg.Appearance.GradientBackground=true;cfg.Appearance.AutoTheme=false;using(var b=TaskbarPainter.Preview(cfg,new SystemSample{Cpu=50})){Check("GDI background gradient has distinct endpoints",b.GetPixel(1,1)!=b.GetPixel(1,b.Height-2));}cfg.Appearance.GradientText=true;cfg.Appearance.GradientGraphs=true;cfg.Appearance.Graphs=true;using(var b=TaskbarPainter.Preview(cfg,new SystemSample{Cpu=50})){Check("GDI gradient text and graphs render",b.Width>0&&b.Height>0);b.Save(Path.Combine(args[0],"taskbar-gradient-preview.png"));}
 Check("insert first position",TaskbarOrderLogic.Target(9,0,false,10)==0);Check("insert last position",TaskbarOrderLogic.Target(0,9,true,10)==9);Check("invalid drag rejected",TaskbarOrderLogic.Target(-1,3,true,10)==-1);
 File.WriteAllText(Path.Combine(args[0],"feature521-results.json"),"{\"checks\":"+checks+",\"failures\":"+failures+"}");return failures==0?0:1;}
}
